<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, shallowRef, watch } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRouter } from 'vue-router'
import AppModal from '@/components/AppModal.vue'
import { evaluateBondExample, readReviewSnapshot, type ReviewSnapshot } from '@/drafting/human-review-integration'
import { PROJECT_SAMPLE_SOURCE_TEXT, PROJECT_SAMPLE_SOURCE_NAME, newCandidateReview, splitCombinedCandidate, correctCandidate, retargetCandidate, adoptCandidate, adoptManual, withdrawAdoption, rerunCandidates, markSourceChanged, acceptedProjectAnswers, type FactKey } from '@/drafting/human-review-project-candidates'

type LocalSource = { id: string; name: string; kind: 'template' | 'correspondence'; file?: File; text?: string; builtin?: boolean }
const sourceOrigin = 'http://127.0.0.1:5191', router = useRouter()
const step = ref(1), reviewTab = ref('template'), sourceMode = ref('empty'), files = ref<LocalSource[]>([])
const frame = ref<HTMLIFrameElement>(), graph = shallowRef<Record<string, unknown> | null>(null), snapshot = shallowRef<ReviewSnapshot | null>(null)
const candidateReview = shallowRef(newCandidateReview())
const loading = ref(true), identified = ref(false), everIdentified = ref(false), ready = ref(false), editorStarted = ref(false)
const reviewLoading = ref(false), reviewLoaded = ref(false), snapshotPending = ref(false), templateConfirmed = ref(false), changed = ref(false), error = ref('')
const edition = ref('word'), selectedFact = ref<FactKey>('months')
const candidateDraft = reactive<{ value: string | number; quote: string; owner: FactKey }>({ value: '', quote: '', owner: 'months' })
const manualValues = reactive<Record<FactKey, string | number>>({ combined: '', foundations: '', months: '' })
const manualReasons = reactive<Record<FactKey, string>>({ combined: '', foundations: '', months: '' })
const previewVisible = ref(false), activeFile = ref('NTT'), documentMode = ref('result'), editingBody = ref(false), bodyDraft = ref(''), savedBody = ref<string | null>(null)
const templateChange = ref(0), savedBodyKey = ref('')
const regenerationOpen = ref(false), traceOpen = ref(false), leaveTarget = ref('')
const runs = ref<Array<{ number: number; candidates: Array<{ label: string; value: string; quote: string; issue: string }> }>>([])
const overrideDraft = reactive({ action: 'follow', text: '', reason: '' })
const targetOverride = ref<{ action: string; text: string; reason: string } | null>(null)
let waitingForLoad = false, snapshotTimer: number | undefined, loadTimer: number | undefined, leaveApproved = false, fileSequence = 0
const steps = [{ number: 1, zh: '资料', en: 'Sources' }, { number: 2, zh: '识别', en: 'Identify candidates' }, { number: 3, zh: '原件核对', en: 'Review sources' }, { number: 4, zh: '采用值及方案', en: 'Adopt values and actions' }, { number: 5, zh: '预览及导出', en: 'Preview and export' }]
const keys: FactKey[] = ['combined', 'foundations', 'months']
const labels: Record<FactKey, { zh: string; en: string }> = { combined: { zh: '是否属于联合合约', en: 'Combined contract applicability' }, foundations: { zh: '是否包含基础工程', en: 'Foundation works included' }, months: { zh: '合约工期（月）', en: 'Contract period (months)' } }
const templateNames = ['NTT · Word', 'SCT · Word', 'SCC · Word版 / Word edition', 'SCC · PDF版 / PDF edition']
const bondQuote = 'Use Appendix G1a with a reduced bond sum for the first twelve (12) months if the tender is for combined contracts with foundation works and with a contract period of 39 months or more.'
const templateFiles = computed(() => files.value.filter(item => item.kind === 'template'))
const correspondence = computed(() => files.value.filter(item => item.kind === 'correspondence'))
const exampleSources = computed(() => sourceMode.value === 'example' && !!graph.value)
const savedRecords = computed(() => (graph.value?.graph as { variables?: unknown[] } | undefined)?.variables?.length ?? 0)
const reviewCount = computed(() => snapshot.value?.summary)
const canConfirmTemplate = computed(() => !!snapshot.value && exampleSources.value && identified.value && snapshot.value.summary.active > 0 && snapshot.value.summary.unconfirmed === 0)
const effectiveAnswers = computed(() => exampleSources.value && identified.value ? acceptedProjectAnswers(candidateReview.value) : { combined: '' as const, foundations: '' as const, months: '' })
const example = computed(() => evaluateBondExample(snapshot.value, effectiveAnswers.value))
const currentCandidate = computed(() => candidateReview.value.candidates[selectedFact.value])
const evidence = computed(() => ({ before: PROJECT_SAMPLE_SOURCE_TEXT.slice(0, currentCandidate.value.sourceStart), selected: PROJECT_SAMPLE_SOURCE_TEXT.slice(currentCandidate.value.sourceStart, currentCandidate.value.sourceEnd), after: PROJECT_SAMPLE_SOURCE_TEXT.slice(currentCandidate.value.sourceEnd) }))
const unresolved = computed(() => keys.filter(key => !candidateReview.value.adopted[key] || candidateReview.value.adopted[key]?.reviewRequired))
const planKey = computed(() => JSON.stringify([templateChange.value, effectiveAnswers.value, edition.value, targetOverride.value]))
const savedBodyStale = computed(() => savedBody.value !== null && savedBodyKey.value !== planKey.value)
const currentBody = computed(() => savedBody.value !== null && !savedBodyStale.value ? savedBody.value : targetOverride.value && targetOverride.value.action !== 'follow' ? targetOverride.value.action === 'amend' ? targetOverride.value.text : '' : example.value.effectEn)
const bodyDirty = computed(() => editingBody.value && bodyDraft.value !== currentBody.value)
const candidateDirty = computed(() => identified.value && (String(candidateDraft.value) !== currentCandidate.value.value || candidateDraft.quote !== currentCandidate.value.quote || candidateDraft.owner !== selectedFact.value))
const actions: Record<string, string> = { follow: '按条件处理 / Follow the condition', retain: '保留 / Retain', amend: '替换 / Amend', delete: '删除 / Delete', not_used: '标为Not used / Mark Not used' }
function fail(caught: unknown) { error.value = caught instanceof Error ? caught.message : String(caught) }
function cancelSnapshot() { window.clearTimeout(snapshotTimer); snapshotPending.value = false }
function invalidateSources() {
  templateChange.value++
  cancelSnapshot(); identified.value = false; snapshot.value = null; templateConfirmed.value = false; previewVisible.value = false
  candidateReview.value = markSourceChanged(candidateReview.value); changed.value = true
}
function loadBuiltIn() {
  invalidateSources(); sourceMode.value = 'example'
  files.value = templateNames.map((name, index) => ({ id: 'template-' + index, name, kind: 'template', builtin: true }))
  files.value.push({ id: 'example-minutes', name: PROJECT_SAMPLE_SOURCE_NAME, kind: 'correspondence', text: PROJECT_SAMPLE_SOURCE_TEXT, builtin: true })
  error.value = ''
}
async function pickFiles(event: Event, kind: LocalSource['kind'], replaceId?: string) {
  const input = event.target as HTMLInputElement, selected = Array.from(input.files ?? []); input.value = ''
  if (!selected.length) return
  invalidateSources(); sourceMode.value = 'custom'
  const additions: LocalSource[] = selected.map(file => ({ id: 'local-' + (++fileSequence), name: file.name, kind, file }))
  files.value = [...files.value.filter(item => !item.builtin && item.id !== replaceId), ...additions]
  for (const item of additions) if (/\.(txt|md|eml)$/i.test(item.name)) try {
    const file = item.file!
    const text = typeof file.text === 'function' ? await file.text() : await new Promise<string>((resolve, reject) => { const reader = new window.FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsText(file) })
    const current = files.value.find(source => source.id === item.id); if (current) current.text = text
  } catch { error.value = '本地文字读取失败；文件仍未解析。 / Local text could not be read; the file remains unparsed.' }
}
function removeFile(id: string) { files.value = files.value.filter(item => item.id !== id); invalidateSources(); sourceMode.value = 'custom' }
function syncCandidate() { candidateDraft.value = currentCandidate.value.value; candidateDraft.quote = currentCandidate.value.quote; candidateDraft.owner = selectedFact.value }
watch(selectedFact, syncCandidate)
function identify() {
  if (candidateDirty.value) { error.value = '请先保存或放弃候选修改，再重新识别。 / Save or discard the candidate edit before re-identifying.'; return }
  if (!exampleSources.value) return
  candidateReview.value = everIdentified.value ? rerunCandidates(candidateReview.value) : newCandidateReview()
  identified.value = true; everIdentified.value = true; previewVisible.value = false; changed.value = true; error.value = ''
  runs.value.push({ number: runs.value.length + 1, candidates: keys.map(key => ({ ...candidateReview.value.candidates[key], label: labels[key].zh })) }); syncCandidate()
}
function candidateAction(task: () => ReturnType<typeof newCandidateReview>, saving = false) { if (candidateDirty.value && !saving) { error.value = '请先保存或放弃当前候选修改。 / Save or discard the current candidate edit first.'; return }; try { candidateReview.value = task(); previewVisible.value = false; changed.value = true; error.value = ''; syncCandidate() } catch (caught) { fail(caught) } }
function saveCandidate() { candidateAction(() => candidateDraft.owner === selectedFact.value ? correctCandidate(candidateReview.value, selectedFact.value, String(candidateDraft.value), candidateDraft.quote) : retargetCandidate(candidateReview.value, selectedFact.value, candidateDraft.owner), true) }
function selectFact(key: FactKey) { if (candidateDirty.value && key !== selectedFact.value) { error.value = '请先保存或放弃当前候选修改。 / Save or discard the current candidate edit first.'; return }; selectedFact.value = key }
function useCandidate(key: FactKey) { candidateAction(() => adoptCandidate(candidateReview.value, key)) }
function useManual(key: FactKey) { candidateAction(() => adoptManual(candidateReview.value, key, String(manualValues[key]), manualReasons[key])) }
function withdraw(key: FactKey) { candidateAction(() => withdrawAdoption(candidateReview.value, key)) }
function valueLabel(value: string | number | undefined) { return value === 'yes' ? '是 / Yes' : value === 'no' ? '否 / No' : value === undefined || value === '' ? '尚未确定 / Unknown' : String(value) }
function send(type: string, payload: Record<string, unknown> = {}) { frame.value?.contentWindow?.postMessage({ type: 'consense:review-prototype:' + type, ...payload }, sourceOrigin) }
function loadSelected() {
  if (!exampleSources.value || !identified.value || reviewLoaded.value) return
  if (!ready.value) { waitingForLoad = true; return }
  waitingForLoad = false; error.value = ''; reviewLoading.value = true
  window.clearTimeout(loadTimer); loadTimer = window.setTimeout(() => { reviewLoading.value = false; error.value = '未收到原件页载入确认，请重试。 / The source review did not acknowledge loading. Retry.' }, 10000)
  send('load', { graph: graph.value })
}
async function openReview(tab = 'template') {
  if (!exampleSources.value || !identified.value) { step.value = 2; return }
  step.value = 3; reviewTab.value = tab
  if (!editorStarted.value) { editorStarted.value = true; await nextTick() }
  if (!reviewLoaded.value && !reviewLoading.value) loadSelected()
}
function requestSnapshot() {
  if (candidateDirty.value) { error.value = '请先保存或放弃候选修改，再继续。 / Save or discard the candidate edit before continuing.'; return }
  if (!ready.value || !reviewLoaded.value || !exampleSources.value || !identified.value) return
  snapshotPending.value = true; error.value = ''; window.clearTimeout(snapshotTimer)
  snapshotTimer = window.setTimeout(() => { snapshotPending.value = false; error.value = '未取得本轮草稿，请先记录或取消原件页调整后重试。 / No review snapshot received. Save or cancel the source edit and retry.' }, 10000)
  send('request-snapshot')
}
function receive(event: MessageEvent) {
  if (event.origin !== sourceOrigin || event.source !== frame.value?.contentWindow || !event.data || typeof event.data !== 'object') return
  const message = event.data
  if (message.type === 'consense:review-prototype:ready') { ready.value = true; if (waitingForLoad) loadSelected() }
  else if (message.type === 'consense:review-prototype:loaded' && reviewLoading.value) { window.clearTimeout(loadTimer); reviewLoaded.value = true; reviewLoading.value = false }
  else if (message.type === 'consense:review-prototype:changed') { templateChange.value++; changed.value = true; snapshot.value = null; templateConfirmed.value = false; previewVisible.value = false }
  else if (message.type === 'consense:review-prototype:error') { window.clearTimeout(loadTimer); reviewLoading.value = false; cancelSnapshot(); error.value = typeof message.message === 'string' ? message.message : '原件核对暂不可用。 / Source review unavailable.' }
  else if (message.type === 'consense:review-prototype:snapshot' && snapshotPending.value && exampleSources.value && identified.value) {
    cancelSnapshot(); const checked = readReviewSnapshot(message), expected = graph.value
    if (!checked) { error.value = '核对草稿不完整，未用于后续步骤。 / The review draft is incomplete and was not used.'; return }
    if (!expected || checked.pack.sourceKey !== expected.sourceKey || !Array.isArray(expected.templates) || !checked.templates.every(binding => { const original = (expected.templates as Record<string, unknown>[]).find(item => item.id === binding.id); return original && ['format', 'originalSha256', 'visualSha256', 'layoutSha256'].every(key => binding[key] === original[key]) })) { error.value = '核对草稿与所选模板不匹配。 / The review draft does not match these templates.'; return }
    snapshot.value = checked; templateConfirmed.value = false; previewVisible.value = false; step.value = 4
  }
}
function confirmTemplate() { if (canConfirmTemplate.value) templateConfirmed.value = true }
function focusSource() { void openReview().then(() => { if (ready.value && reviewLoaded.value) send('focus', { id: 'review-8' }) }) }
function focusFact(key: FactKey) { selectFact(key); void openReview('facts') }
function preview() { if (!snapshot.value || !exampleSources.value || !identified.value) return; previewVisible.value = !savedBodyStale.value; activeFile.value = 'NTT'; documentMode.value = 'result'; step.value = 5 }
function saveOverride() { if (!overrideDraft.reason.trim() || overrideDraft.action === 'amend' && !overrideDraft.text.trim()) { error.value = '请填写理由，替换时还需准确新文字。 / Supply a reason and exact replacement text.'; return }; targetOverride.value = { ...overrideDraft }; changed.value = true; previewVisible.value = false }
function editBody() { bodyDraft.value = currentBody.value; editingBody.value = true }
function saveBody() { savedBody.value = bodyDraft.value; savedBodyKey.value = planKey.value; editingBody.value = false; changed.value = true }
function regenerate() { if (savedBody.value !== null || bodyDirty.value) regenerationOpen.value = true; else finishRegeneration() }
function finishRegeneration() { savedBody.value = null; editingBody.value = false; regenerationOpen.value = false; previewVisible.value = !!snapshot.value && exampleSources.value; documentMode.value = 'result' }
function go(number: number) { if (bodyDirty.value && number !== step.value) { error.value = '请先保存或放弃示例正文修改。 / Save or discard the body edit first.'; return }; if (number === 3) { void openReview(); return }; if (number >= 4 && !snapshot.value) { void openReview(); return }; if (number === 5) { preview(); return }; step.value = number }
watch(edition, () => { templateConfirmed.value = false; previewVisible.value = false })
function guard(to: { fullPath: string }) { if (changed.value && !leaveApproved) { leaveTarget.value = to.fullPath; return false }; return true }
onBeforeRouteLeave(guard); onBeforeRouteUpdate(to => to.query.reviewPrototype === '1' ? true : guard(to))
function leave() { leaveApproved = true; const target = leaveTarget.value; leaveTarget.value = ''; void router.push(target) }
function beforeUnload(event: BeforeUnloadEvent) { if (changed.value) { event.preventDefault(); event.returnValue = '' } }
onMounted(async () => {
  window.addEventListener('message', receive); window.addEventListener('beforeunload', beforeUnload)
  try { const response = await fetch('/__review-prototype/graph.json', { cache: 'no-store' }); if (!response.ok) throw Error('本机示例图谱暂不可用。 / Local example graph unavailable.'); const saved = await response.json(); if (!saved || saved.kind !== 'consense-template-graph-v1' || !Array.isArray(saved.templates) || saved.templates.length !== 4 || !saved.graph || !Array.isArray(saved.graph.variables)) throw Error('示例图谱不完整。 / Incomplete example graph.'); graph.value = saved } catch (caught) { fail(caught) } finally { loading.value = false }
})
onBeforeUnmount(() => { window.removeEventListener('message', receive); window.removeEventListener('beforeunload', beforeUnload); cancelSnapshot(); window.clearTimeout(loadTimer) })
</script>

<template>
<section class="integration-prototype" data-human-review-integration>
  <header class="intro"><div><span class="prototype-label">交互原型 <span lang="en">Interaction prototype</span></span><h1>合约起草：从资料识别到原件核对<span class="en">Contract drafting: identify sources, review them, then adopt project facts</span></h1><p>上传模板与沟通资料，先识别候选，再在原件纠错、采用本项目资料，最后核对处理方案。<span class="en">Upload templates and correspondence, identify candidates, correct them on the source, adopt project facts and inspect the proposed amendments.</span></p></div><p class="boundary">本机交互示例<span class="en">Local interaction example</span><small>未连接正式识别、编译及导出服务<span class="en">Formal extraction, compilation and export are not connected</span></small></p></header>
  <nav class="prototype-steps" aria-label="起草流程 / Drafting workflow"><button v-for="item in steps" :key="item.number" class="step-button" :class="{ active: step === item.number }" :aria-current="step === item.number ? 'step' : undefined" @click="go(item.number)"><span class="step-number">{{ item.number }}</span><span>{{ item.zh }}<span class="en">{{ item.en }}</span></span></button></nav>
  <p v-if="error" class="notice error" role="alert">{{ error }}</p>
  <p v-if="sourceMode === 'custom'" class="notice">自选文件仅暂存在本页，尚未解析。内置候选及模板确认已失效；不会用示例原件冒充这些文件。<span class="en">Selected files are held in this page and remain unparsed. Built-in candidates and confirmation are invalid; built-in pages are not previews of your files.</span></p>

  <section v-show="step === 1" class="panel">
    <div class="panel-heading"><div><h2>模板与项目沟通资料<span class="en">Templates and project correspondence</span></h2><p>模板提供问题和改文要求；沟通资料提供本项目事实。<span class="en">Templates supply questions and amendment requirements. Correspondence supplies project facts.</span></p></div><button class="btn primary" :disabled="loading || !graph" @click="loadBuiltIn">载入内置模板与演示会议纪要<span class="en">Load built-in templates and fictional meeting notes</span></button></div>
    <div class="source-section"><div class="panel-heading"><h3>标准模板<span class="en">Standard templates</span></h3><label class="btn">上传模板<span class="en">Select template files</span><input data-template-upload type="file" accept=".doc,.docx,.pdf,.txt,.md" multiple @change="pickFiles($event, 'template')"></label></div><p class="hint">选文件不等于已解析。Word优先；SCC两版独立。<span class="en">Selecting a file does not parse it. Word is preferred; SCC editions remain separate.</span></p><p v-if="!templateFiles.length" class="hint">尚未选择模板。 / No templates selected.</p><article v-for="file in templateFiles" :key="file.id" class="file-row"><div><strong>{{ file.name }}</strong><span class="state">{{ file.builtin ? '内置示例原件 / Built-in example source' : '已暂存 · 未解析 / Staged · unparsed' }}</span></div><label class="btn">替换 / Replace<input :data-template-replace="file.id" type="file" accept=".doc,.docx,.pdf,.txt,.md" @change="pickFiles($event, 'template', file.id)"></label><details v-if="file.text !== undefined"><summary>查看本地原文 / Read local text</summary><pre>{{ file.text }}</pre></details><p v-else-if="!file.builtin" class="hint">未生成文档预览。 / No document preview generated.</p></article></div>
    <fieldset class="edition"><legend>本项目SCC版本 / SCC edition for this project</legend><label><input v-model="edition" type="radio" value="word"> Word版 / Word edition</label><label><input v-model="edition" type="radio" value="pdf"> PDF版 / PDF edition</label><p v-if="edition === 'pdf'" class="hint">PDF可供核对，但该版未提供可编辑原件，不能正式生成。<span class="en">The PDF is reviewable; no editable original for this edition is supplied.</span></p></fieldset>
    <div class="source-section"><div class="panel-heading"><h3>项目沟通资料<span class="en">Project correspondence</span></h3><label class="btn">上传沟通资料<span class="en">Select correspondence</span><input data-correspondence-upload type="file" accept=".doc,.docx,.pdf,.txt,.md,.eml,.msg" multiple @change="pickFiles($event, 'correspondence')"></label></div><p v-if="!correspondence.length" class="hint">尚未选择沟通资料。 / No correspondence selected.</p><article v-for="file in correspondence" :key="file.id" class="file-row"><div><strong>{{ file.name }}</strong><span class="state">{{ file.builtin ? '明确虚构 · 交互示例 / Fictional interaction example' : '已暂存 · 未解析 / Staged · unparsed' }}</span></div><button class="btn" :data-remove-correspondence="file.id" @click="removeFile(file.id)">从本页项目移除<span class="en">Remove from this page's project</span></button><details v-if="file.text !== undefined"><summary>查看原始文字 / Read source text</summary><pre>{{ file.text }}</pre></details><p v-else class="hint">未生成原文预览。 / No document preview generated.</p></article></div>
    <footer class="actions"><button class="btn primary" :disabled="!exampleSources" @click="step = 2">继续识别候选<span class="en">Continue to candidate identification</span></button></footer>
  </section>

  <section v-show="step === 2" class="panel">
    <div class="panel-heading"><div><h2>先识别，再核对<span class="en">Identify first, then review</span></h2><p>只对内置示例演示识别；未调用模型，所有结果仍是候选。<span class="en">Offline identification is available only for the built-in example. No model is called; results remain candidates.</span></p></div><div class="row"><button class="btn" :disabled="!runs.length" @click="traceOpen = true">识别记录 / Identification history</button><button class="btn primary" :disabled="!exampleSources" @click="identify">{{ identified ? '重新演示识别' : '演示识别' }}<span class="en">{{ identified ? 'Repeat the offline example' : 'Identify example candidates' }}</span></button></div></div>
    <p v-if="!exampleSources" class="notice">自传文件尚未解析，不能套用内置候选。<span class="en">Selected files remain unparsed; built-in candidates cannot be assigned to them.</span></p>
    <template v-if="identified && exampleSources">
      <article class="requirement-card"><span class="source-format">NTT · 原文指导要求 / Source guidance</span><h3>这段原文要求处理什么？<span class="en">What does this passage require?</span></h3><blockquote>{{ bondQuote }}</blockquote><div class="requirement-map"><p><strong>候选问题 / Candidate questions</strong><br>是否联合合约、是否含基础、工期（月）。<span class="en">Combined contract, foundation works, and duration in months.</span></p><p><strong>共同条件 / Combined conditions</strong><br>两事实为是，且工期不少于39个月；未知不是否。<span class="en">Both facts are Yes and duration is at least 39 months. Unknown is not No.</span></p><p><strong>处理要求 / Amendment</strong><br>按条件决定NTT第10条担保书G1／G1a；原件核准确落点。<span class="en">Choose G1 or G1a in NTT clause 10; verify the exact passage on the source.</span></p></div><p class="hint">{{ savedRecords }}项记录来自已有核对草稿；本轮未重新执行全量动态识别。<span class="en">The {{ savedRecords }} records are from the saved review. Full dynamic extraction was not run.</span></p></article>
      <h3>沟通资料中的候选事实<span class="en">Candidate facts from fictional correspondence</span></h3><p v-if="!candidateReview.compoundSplit" class="notice">旧合取项“包含基础的联合合约”尚未分别核对，不能直接分成两个已采用事实。<span class="en">The legacy compound requires separate checks; it cannot be copied into two adopted facts.</span></p>
      <div class="candidate-summary"><article v-for="key in keys" :key="key"><strong>{{ labels[key].zh }}<span class="en">{{ labels[key].en }}</span></strong><p>{{ valueLabel(candidateReview.candidates[key].value) }}</p><p class="hint">{{ candidateReview.candidates[key].issue || '本次采用状态请到下一步核对 / Check the current adoption in the next stage' }}</p><blockquote>{{ candidateReview.candidates[key].quote }}</blockquote><button class="btn" @click="focusFact(key)">到原文核对 / Review on the source</button></article></div><details><summary>虚构会议纪要原文 / Fictional meeting notes</summary><pre>{{ PROJECT_SAMPLE_SOURCE_TEXT }}</pre></details>
    </template>
    <footer class="actions"><button class="btn" @click="step = 1">返回资料 / Back to sources</button><button class="btn primary" :disabled="!identified || !exampleSources" @click="openReview()">进入原件核对<span class="en">Review the identified sources</span></button></footer>
  </section>

  <section v-show="step === 3" class="review-stage">
    <div class="review-toolbar"><div><h2>在原件核对理解与归属<span class="en">Review the interpretation and ownership on the source</span></h2><p>模板规则与沟通事实分别核对；纠正候选仍不等于采用。<span class="en">Template rules and correspondence facts are reviewed separately. Correction does not adopt a candidate.</span></p></div><button class="btn" @click="step = 2">返回识别结果 / Back to identification</button></div>
    <nav class="review-tabs"><button class="btn" :class="{ primary: reviewTab === 'template' }" @click="reviewTab = 'template'">模板规则 / Template rules</button><button class="btn" :class="{ primary: reviewTab === 'facts' }" @click="reviewTab = 'facts'">沟通事实 / Correspondence facts</button></nav>
    <p v-if="!identified || !exampleSources" class="notice">先识别本次来源候选，再进入原件核对。 / Identify current-source candidates first.</p>
    <div v-show="reviewTab === 'template' && identified && exampleSources"><details class="review-guide"><summary>核对时的六个问题 / Six review questions</summary><ol><li>这段要求处理什么？ / What is required?</li><li>怎么回答？ / What answer shape?</li><li>属于哪里、适用于谁？ / Which group or item owns it?</li><li>前提是什么，哪些条件共同判断？ / Prerequisites and combined conditions?</li><li>答案怎样得出？ / How is the answer obtained?</li><li>改哪段、怎样改？ / Which passage changes, and how?</li></ol></details><p v-if="!ready || reviewLoading" class="notice" role="status">正在连接或载入已绑定原件草稿… / Connecting or loading the bound source draft…</p><button v-else-if="!reviewLoaded" class="btn" @click="loadSelected">重试载入 / Retry loading</button></div>
    <iframe v-if="editorStarted" v-show="step === 3 && reviewTab === 'template' && identified && exampleSources" ref="frame" class="source-frame" :src="sourceOrigin + '/'" title="原件人工审核 / Source review" allow="fullscreen" />
    <div v-if="reviewTab === 'facts' && identified && exampleSources" class="panel fact-workspace">
      <div><h3>{{ PROJECT_SAMPLE_SOURCE_NAME }}<span class="en">Fictional source · interaction example only</span></h3><p class="meeting-source">{{ evidence.before }}<mark>{{ evidence.selected }}</mark>{{ evidence.after }}</p><p class="hint">高亮为当前引用位置；改建议值不会改原文。<span class="en">Highlighted quotation; correcting a candidate does not change the source.</span></p><div class="compound-card"><strong>旧合取项：包含基础的联合合约<span class="en">Legacy compound: combined contract with foundation works</span></strong><blockquote>{{ candidateReview.compoundCandidate.quote }}</blockquote><p class="hint">拆成两个候选后仍须分别核对，不自动采用。 / Splitting does not adopt either fact.</p><button class="btn" :disabled="candidateReview.compoundSplit" @click="candidateAction(() => splitCombinedCandidate(candidateReview))">分开核对两个事实<span class="en">Review the two facts separately</span></button></div><nav class="fact-index"><button v-for="key in keys" :key="key" class="btn" :class="{ primary: selectedFact === key }" @click="selectFact(key)">{{ labels[key].zh }}<span class="en">{{ labels[key].en }}</span></button></nav></div>
      <form class="fact-correction" @submit.prevent="saveCandidate"><h3>这条建议被理解成什么？<span class="en">How was this candidate interpreted?</span></h3><p class="hint">{{ currentCandidate.type === 'number' ? '回答方式：数字（月） / Number of months' : '回答方式：是／否 / Yes or No' }}</p><label>建议值 / Candidate value<input v-if="selectedFact === 'months'" v-model="candidateDraft.value" data-candidate-value type="number" min="0" step="any"><select v-else v-model="candidateDraft.value" data-candidate-value><option value="">未知 / Unknown</option><option value="yes">是 / Yes</option><option value="no">否 / No</option></select></label><label>交换这两项候选的归属<span class="en">Swap ownership of these two candidates</span><select v-model="candidateDraft.owner" data-candidate-owner><option v-for="key in keys" :key="key" :value="key">{{ labels[key].zh }} / {{ labels[key].en }}</option></select></label><label>原文依据 / Source quotation<textarea v-model="candidateDraft.quote" data-candidate-quote rows="3" /></label><p v-if="currentCandidate.issue" class="notice">{{ currentCandidate.issue }}</p><button class="btn primary" type="submit">{{ candidateDraft.owner === selectedFact ? '保存候选纠正' : '交换这两项候选的归属' }}<span class="en">{{ candidateDraft.owner === selectedFact ? 'Keep the corrected candidate' : 'Swap ownership of these two candidates' }}</span></button><button v-if="candidateDirty" class="btn" type="button" @click="syncCandidate(); error = ''">放弃候选修改 / Discard candidate edit</button><p class="hint">选择另一个问题时只交换原有两条候选；值的纠正请先保存。两种动作都不会采用。<span class="en">Choosing another owner swaps the two existing candidates. Save value corrections separately first. Neither action adopts a fact.</span></p></form>
    </div>
    <div class="review-footer"><p>原件页“模板图谱”可真实本机保存或下载备份；继续只取得本页模板快照，沟通事实仍需分别采用。<span class="en">Use Template graphs in the source editor for local saving. Continue captures an in-memory template snapshot; facts still need adoption.</span></p><button class="btn primary" :disabled="!ready || !reviewLoaded || snapshotPending || !identified || !exampleSources" @click="requestSnapshot()">{{ snapshotPending ? '正在取得模板核对草稿…' : '带着本轮草稿继续' }}<span class="en">Continue with this review draft</span></button></div>
  </section>

  <section v-show="step === 4" class="panel">
    <div class="panel-heading"><div><h2>采用本项目事实，再判断处理方案<span class="en">Adopt project facts before deciding amendments</span></h2><p>模板草稿、模板确认、项目采用、成稿分别保留；未采用和待复核值不参与条件判断。<span class="en">Rule drafts, template confirmation, fact adoption and document drafts remain separate. Unadopted or review-required values are excluded.</span></p></div><button class="btn" @click="traceOpen = true">识别记录 / Identification history</button></div>
    <p v-if="!snapshot" class="notice">模板核对已变化，需重取草稿；项目已采用事实仍保留。<span class="en">The template changed; capture a fresh review. Adopted project facts are retained.</span></p>
    <div class="template-confirmation"><div><h3>确认模板用于起草<span class="en">Confirm the template for drafting</span></h3><p v-if="templateConfirmed" class="hint">仅为本页模板确认示例，未发布至服务。 / Page-local confirmation only.</p><p v-else-if="!snapshot" class="hint">先取得本轮模板草稿。 / Capture the current review first.</p><p v-else-if="!snapshot.summary.active" class="hint">空图谱不能确认。 / An empty graph cannot be confirmed.</p><p v-else class="hint">{{ reviewCount?.records }}项记录，{{ reviewCount?.active }}项未停用、{{ reviewCount?.unconfirmed }}项未确认。<span class="en">{{ reviewCount?.unconfirmed }} records remain unconfirmed. Template confirmation does not adopt project facts.</span></p></div><button class="btn" :disabled="!canConfirmTemplate || templateConfirmed" @click="confirmTemplate">确认此版模板用于起草<span class="en">Confirm this template version for drafting</span></button></div>
    <div class="adoption-cards"><article v-for="key in keys" :key="key" class="adoption-card"><h3>{{ labels[key].zh }}<span class="en">{{ labels[key].en }}</span></h3><span class="state">候选 · {{ valueLabel(candidateReview.candidates[key].value) }}</span><blockquote>{{ candidateReview.candidates[key].quote }}</blockquote><p v-if="candidateReview.candidates[key].issue" class="hint">{{ candidateReview.candidates[key].issue }}</p><button class="btn" :data-adopt-candidate="key" :disabled="!!candidateReview.candidates[key].issue || !candidateReview.candidates[key].value || !identified || !exampleSources" @click="useCandidate(key)">采用这个候选<span class="en">Adopt this candidate</span></button><button class="btn text-link" @click="focusFact(key)">回原文纠正 / Correct on source</button><p class="adopted-state" :data-adopted-state="key"><strong>本次采用：{{ valueLabel(candidateReview.adopted[key]?.value) }}</strong><span v-if="candidateReview.adopted[key]?.reviewRequired" class="state">保留旧值 · 待复核 / Retained · review required</span><span v-else class="en">{{ candidateReview.adopted[key] ? candidateReview.adopted[key]?.origin === 'manual' ? 'Manually adopted' : 'Candidate adopted' : 'Not adopted' }}</span><small v-if="candidateReview.adopted[key]?.reason">{{ candidateReview.adopted[key]?.reason }}</small></p><button v-if="candidateReview.adopted[key]" class="btn" :data-withdraw="key" @click="withdraw(key)">撤销本次采用 / Withdraw adoption</button><details><summary>人工填写并采用 / Enter and adopt manually</summary><label>本次取值 / Project value<input v-if="key === 'months'" v-model="manualValues[key]" :data-manual-value="key" type="number" min="0" step="any"><select v-else v-model="manualValues[key]" :data-manual-value="key"><option value="">未知 / Unknown</option><option value="yes">是 / Yes</option><option value="no">否 / No</option></select></label><label>采用理由或补充依据 / Reason or additional evidence<textarea v-model="manualReasons[key]" :data-manual-reason="key" rows="2" /></label><button class="btn" :data-adopt-manual="key" :disabled="!manualReasons[key].trim() || manualValues[key] === '' || !identified || !exampleSources" @click="useManual(key)">人工填写并采用 / Adopt the manual value</button></details></article></div>
    <article class="derived-result" aria-live="polite"><span class="result-kind">一条有来源的条件示例 / One source-bound condition</span><h3>{{ example.nameZh }}<span class="en">{{ example.nameEn }}</span></h3><template v-if="example.status === 'resolved'"><strong>{{ example.resultZh }}<span class="en">{{ example.resultEn }}</span></strong><p>{{ example.effectZh }}<span class="en">{{ example.effectEn }}</span></p></template><p v-else-if="example.status === 'pending'">已采用资料不足，尚不能确定；未采用不是“否”。<span class="en">Adopted facts are insufficient. Unadopted is not No.</span></p><p v-else>定义、条件或关联需要重核，不推测处理结果。<span class="en">Definitions, conditions or bindings need review. No outcome is inferred.</span></p><button class="btn text-link" @click="focusSource">回模板原文核对规则 / Read this rule on the template</button></article>
