    <footer class="actions"><button class="btn" @click="openReview()">继续原件核对 / Continue source review</button><button class="btn" @click="step = 2">重新识别候选 / Re-identify candidates</button><button class="btn primary" :disabled="!snapshot || !identified || !exampleSources" @click="preview">查看示例处理结果<span class="en">Preview the illustrative result</span></button></footer>
